SELECT datetime(strftime('%s', ms_tshark_packet_time) / #{bucketSeconds} * #{bucketSeconds}, 'unixepoch') AS t,
COUNT(*) AS packets, COALESCE(SUM(ms_tshark_packet_length), 0) AS bytes
FROM ms_tshark_packet
WHERE ms_tshark_packet_session_id = #{sessionId}
GROUP BY strftime('%s', ms_tshark_packet_time) / #{bucketSeconds} * #{bucketSeconds}
ORDER BY t

